const SECURITY_HEADERS = {"Content-Security-Policy":"default-src 'self'; base-uri 'none'; object-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'none'; media-src 'none'; frame-src 'none'; frame-ancestors 'none'; worker-src 'none'; manifest-src 'self'; form-action 'none'; upgrade-insecure-requests","Referrer-Policy":"no-referrer","X-Content-Type-Options":"nosniff","X-Frame-Options":"DENY","X-Permitted-Cross-Domain-Policies":"none","X-DNS-Prefetch-Control":"off","Cross-Origin-Opener-Policy":"same-origin","Cross-Origin-Resource-Policy":"same-origin","Permissions-Policy":"accelerometer=(), autoplay=(), camera=(), display-capture=(), encrypted-media=(), fullscreen=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), midi=(), payment=(), picture-in-picture=(), publickey-credentials-get=(), usb=(), web-share=()","Strict-Transport-Security":"max-age=31536000"};

function responseHeaders(asset, pathname) {
  return {
    ...SECURITY_HEADERS,
    'Content-Type': asset?.contentType ?? 'text/plain; charset=utf-8',
    'Cache-Control': pathname === '/index.html' || pathname === '/.well-known/security.txt'
      ? 'no-cache'
      : 'public, max-age=3600',
    ...(asset ? { ETag: asset.etag } : {}),
  };
}

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

export default {
  async fetch(request) {
    const method = request.method.toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
      return new Response('Method not allowed', {
        status: 405,
        headers: { ...responseHeaders(null, ''), Allow: 'GET, HEAD' },
      });
    }

    let pathname;
    try { pathname = decodeURIComponent(new URL(request.url).pathname); }
    catch { return new Response('Bad request', { status: 400, headers: responseHeaders(null, '') }); }
    if (pathname === '/') pathname = '/index.html';
    const asset = ASSETS[pathname];
    if (!asset) return new Response('Not found', { status: 404, headers: responseHeaders(null, pathname) });

    const headers = responseHeaders(asset, pathname);
    if (request.headers.get('If-None-Match') === asset.etag) {
      return new Response(null, { status: 304, headers });
    }
    return new Response(method === 'HEAD' ? null : decodeBase64(asset.body), { status: 200, headers });
  },
};
